"""Emit ngspice SPICE for a token sequence that contains NPN/PNP devices.

lna/to_spice.py (shared, not edited here) only implements NM/PM/R/C/L in its
Netlist.emit() -- confirmed by running it on the ihp_gps_lna_npn sequence:

    cannot emit 12 device(s): NPN1: unsupported device type ...

AnalogGenie's own vocabulary and lna/topology.py's LEGAL/DEV_PREFIXES already
support NPN/PNP (3-terminal C/B/E), so this is a real gap in the shared
emitter, not a limitation of the data. This script is a minimal, owned-path
(lna/data/external/_tools/) extension that mirrors to_spice.py's structure
(same param-naming discipline, rshunt, finite inductor Q, db floor, port
setup -- see lna/FINDINGS.md fixes X1-X6) and adds a Q-element branch, purely
so the ihp-gps-lna-npn prototype can be simulated end-to-end without touching
the shared file. It intentionally does not try to be a general replacement
for to_spice.py -- just enough to unblock this one circuit family.

    python to_spice_bjt_ext.py <seq_file> -o <out.cir>
"""
import argparse
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
LNA_DIR = os.path.dirname(os.path.dirname(os.path.dirname(HERE)))
sys.path.insert(0, LNA_DIR)
from topology import PIN_RE, Topology, base_of, parse_arrow_file  # noqa: E402

DEFAULT_MODELS = os.path.abspath(os.path.join(
    LNA_DIR, "..", "AutoCkt", "repo", "eval_engines", "ngspice",
    "ngspice_inputs", "spice_models", "45nm_bulk.txt"))

DEFAULTS = {"NM": ("40u", "45n"), "PM": ("80u", "45n"),
            "R": "1k", "C": "1p", "L": "1n", "NPN": None, "PNP": None}


def build(topo, models=DEFAULT_MODELS, vdd=1.1, vbias=0.5,
          freq_lo=1e9, freq_hi=4e9, points=201, inductor_q=12):
    t = topo
    node_of_pin, node_names = {}, {}
    counter = 0
    for root, members in t.nodes.items():
        named = sorted(m for m in members if m in t.nets)
        name = named[0] if named else f"n{counter}"
        if name == "VSS":
            name = "0"
        if not named:
            counter += 1
        node_names[root] = name
        for m in members:
            if PIN_RE.match(m):
                node_of_pin[m] = name

    def pin_node(dev, pin):
        return node_of_pin.get(f"{dev}_{pin}")

    L = []
    A = L.append
    A("* Auto-generated by lna/data/external/_tools/to_spice_bjt_ext.py")
    A("* Extends lna/to_spice.py's approach with NPN/PNP support (see module docstring).")
    A("")
    A(f".include {models.replace(os.sep, '/')}")
    A(".model qnpn npn(bf=100 is=1e-16 vaf=50 rb=50 re=1 tf=10p cjc=20f cje=20f)")
    A(".model qpnp pnp(bf=50 is=1e-16 vaf=50 rb=50 re=1 tf=20p cjc=20f cje=20f)")
    A("")
    A(f".param pVDD={vdd} pVB={vbias}")
    lo, hi = freq_lo, freq_hi
    f0 = (lo * hi) ** 0.5
    if inductor_q:
        A(f".param pINDQ={inductor_q} pINDW0={2 * 3.141592653589793 * f0:g}")
    for d in sorted(t.devices):
        b = base_of(d)
        if b in ("NM", "PM"):
            w, l = DEFAULTS[b]
            A(f".param p{d}W={w} p{d}L={l}")
        elif b in ("R", "C", "L"):
            A(f".param p{d}V={DEFAULTS[b]}")
    A("")

    used = set(t.nets)
    A("Vsup VDD 0 dc {pVDD}")
    for n in sorted(used):
        if n.startswith("VB") or n.startswith("VCM") or n.startswith("VREF"):
            A(f"V{n} {n} 0 dc {{pVB}}")
    A("")

    has_in, has_out = "VIN1" in used, "VOUT1" in used
    two_port = has_in and has_out
    if two_port:
        A("Vp1 p1 0 dc 0 ac 1 portnum 1 z0 50")
        A("Cp1 p1 VIN1 10p")
        A("Cp2 VOUT1 p2 10p")
        A("Vp2 p2 0 dc 0 ac 0 portnum 2 z0 50")
    elif has_out:
        A("Rload VOUT1 0 50")
    A("")

    for d in sorted(t.devices):
        b = base_of(d)
        if b == "NM":
            A(f"M{d} {pin_node(d,'D')} {pin_node(d,'G')} {pin_node(d,'S')} {pin_node(d,'B')} "
              f"nmos W={{p{d}W}} L={{p{d}L}}")
        elif b == "PM":
            A(f"M{d} {pin_node(d,'D')} {pin_node(d,'G')} {pin_node(d,'S')} {pin_node(d,'B')} "
              f"pmos W={{p{d}W}} L={{p{d}L}}")
        elif b == "R":
            A(f"R{d} {pin_node(d,'P')} {pin_node(d,'N')} {{p{d}V}}")
        elif b == "C":
            A(f"C{d} {pin_node(d,'P')} {pin_node(d,'N')} {{p{d}V}}")
        elif b == "L":
            p, n = pin_node(d, 'P'), pin_node(d, 'N')
            if inductor_q:
                A(f"L{d} {p} nq{d} {{p{d}V}}")
                A(f"RQ{d} nq{d} {n} {{pINDW0*p{d}V/pINDQ}}")
            else:
                A(f"L{d} {p} {n} {{p{d}V}}")
        elif b == "NPN":
            A(f"Q{d} {pin_node(d,'C')} {pin_node(d,'B')} {pin_node(d,'E')} qnpn")
        elif b == "PNP":
            A(f"Q{d} {pin_node(d,'C')} {pin_node(d,'B')} {pin_node(d,'E')} qpnp")
    A("")

    A(".option rshunt=1e12")
    A(".control")
    A("op")
    if two_port:
        A(f"sp lin {points} {lo:g} {hi:g} 1")
        A("let s11db = db(mag(S_1_1) + 1e-30)")
        A("let s21db = db(mag(S_2_1) + 1e-30)")
        A("print vecmin(s11db) vecmax(s21db)")
        A(f"noise v(p2) Vp1 dec 20 {lo:g} {hi:g} 1")
    A(".endc")
    A(".end")
    return "\n".join(L) + "\n"


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("sequence")
    ap.add_argument("-o", "--out", required=True)
    ap.add_argument("--inductor-q", type=float, default=12.0)
    args = ap.parse_args()
    toks = parse_arrow_file(args.sequence)
    topo = Topology(toks)
    score, crit = topo.lna_score()
    print(f"devices {topo.n_devices}  inductors {topo.n_inductors}  "
          f"nodes {len(topo.nodes)}  LNA score {score}/5")
    print("structurally valid:", topo.valid)
    text = build(topo, inductor_q=args.inductor_q)
    with open(args.out, "w", encoding="utf-8") as fh:
        fh.write(text)
    print(f"wrote {args.out}")


if __name__ == "__main__":
    main()
